// -------------------------------
// NBA Bets Dashboard (with DvP + Chart Wheel)
// -------------------------------

const JSON_PATH = "./bets_to_place.json";
const DVP_CSV_PATH = "./dvp.csv";

// Charts (generated by morning_eval.py)
const METRICS_CSV_PATH = "./metrics_history.csv";
const BUCKET_CSV_PATH = "./bucket_accuracy_latest.csv";

const statusEl = document.getElementById("status");
const updatedEl = document.getElementById("updated");

const searchEl = document.getElementById("search");
const typeFilterEl = document.getElementById("typeFilter");
const sortByEl = document.getElementById("sortBy");

const bodyEl = document.getElementById("betsBody");

// Optional DvP UI
const dvpStatusEl = document.getElementById("dvpStatus");
const dvpUpdatedEl = document.getElementById("dvpUpdated");
const dvpPosEl = document.getElementById("dvpPos");
const dvpBodyEl = document.getElementById("dvpBody");

// Charts UI
const chartsStatusEl = document.getElementById("chartsStatus");
const chartsUpdatedEl = document.getElementById("chartsUpdated");
const metricsCanvas = document.getElementById("metricsChart");
const bucketCanvas = document.getElementById("bucketChart");
const metricsNoteEl = document.getElementById("metricsChartNote");
const bucketNoteEl = document.getElementById("bucketChartNote");

// Wheel UI
const wheelEl = document.getElementById("chartWheel");
const wheelPrevBtn = document.getElementById("wheelPrev");
const wheelNextBtn = document.getElementById("wheelNext");
const wheelCounterEl = document.getElementById("wheelCounter");

let rows = [];    // normalized bets
let dvpRows = []; // normalized dvp rows

function setStatus(text, kind = "") {
  statusEl.textContent = text;
  statusEl.classList.remove("ok", "bad");
  if (kind) statusEl.classList.add(kind);
}

function setDvpStatus(text, kind = "") {
  if (!dvpStatusEl) return;
  dvpStatusEl.textContent = text;
  dvpStatusEl.classList.remove("ok", "bad");
  if (kind) dvpStatusEl.classList.add(kind);
}

function setChartsStatus(text, kind = "") {
  if (!chartsStatusEl) return;
  chartsStatusEl.textContent = text;
  chartsStatusEl.classList.remove("ok", "bad");
  if (kind) chartsStatusEl.classList.add(kind);
}

function parseCSV(text) {
  // Basic CSV parser (assumes no commas inside quoted fields)
  const lines = text.trim().split(/\r?\n/);
  if (lines.length < 2) return [];

  const headers = lines[0].split(",").map((h) => h.trim());
  const out = [];

  for (let i = 1; i < lines.length; i++) {
    if (!lines[i].trim()) continue;
    const cols = lines[i].split(",").map((c) => c.trim());
    const obj = {};
    headers.forEach((h, idx) => (obj[h] = cols[idx] ?? ""));
    out.push(obj);
  }
  return out;
}

function toProbNumber(obj) {
  // supports "probability" (0-1) or "probability_pct" like "73.2%"
  if (obj.probability && obj.probability !== "") {
    const n = Number(obj.probability);
    return Number.isFinite(n) ? n : null;
  }
  if (obj.probability_pct) {
    const n = Number(String(obj.probability_pct).replace("%", ""));
    return Number.isFinite(n) ? n / 100 : null;
  }
  return null;
}

function normalizeBets(raw) {
  return raw.map((r) => {
    const p = toProbNumber(r);
    const pct = p !== null ? (Math.round(p * 1000) / 10).toFixed(1) + "%" : "";
    return {
      bet: r.bet || "",
      bet_type: r.bet_type || "",
      probability: p,
      probability_pct: r.probability_pct || pct,
      opponent: (r.opponent || "").toUpperCase(),
      date: r.date || "",
      game_id: r.game_id || "",
      // Optional future fields
      position: (r.position || "").toUpperCase(),
      team: (r.team || "").toUpperCase(),
    };
  });
}

function normalizeDvp(raw) {
  // expects columns from dvp.csv:
  // defense_team, position, value, rank_pos, matchup_grade
  return raw
    .map((r) => ({
      defense_team: (r.defense_team || r.DEFENSE_TEAM || "").toUpperCase(),
      position: (r.position || r.POSITION || "").toUpperCase(),
      value: toNumber(r.value ?? r.VALUE),
      rank_pos: toNumber(r.rank_pos ?? r.RANK_POS),
      matchup_grade: (r.matchup_grade || r.MATCHUP_GRADE || "").toUpperCase(),
    }))
    .filter((r) => r.defense_team && r.position);
}

function toNumber(x) {
  const n = Number(String(x ?? "").trim());
  return Number.isFinite(n) ? n : null;
}

function renderBets(list) {
  if (!list.length) {
    bodyEl.innerHTML = `<tr><td colspan="6" class="muted">No rows to display.</td></tr>`;
    return;
  }

  bodyEl.innerHTML = list
    .map(
      (r) => `
    <tr>
      <td><strong>${escapeHtml(r.bet)}</strong></td>
      <td>${escapeHtml(r.bet_type)}</td>
      <td>${escapeHtml(r.probability_pct)}</td>
      <td>${escapeHtml(r.opponent)}</td>
      <td>${escapeHtml(r.date)}</td>
      <td class="muted">${escapeHtml(r.game_id)}</td>
    </tr>
  `
    )
    .join("");
}

function renderDvpTable(position = "PG") {
  if (!dvpBodyEl) return;

  const pos = (position || "PG").toUpperCase();
  const list = dvpRows
    .filter((r) => r.position === pos)
    .sort((a, b) => (a.rank_pos ?? 999) - (b.rank_pos ?? 999));

  if (!list.length) {
    dvpBodyEl.innerHTML = `<tr><td colspan="4" class="muted">No DvP rows to display.</td></tr>`;
    return;
  }

  dvpBodyEl.innerHTML = list
    .map(
      (r) => `
      <tr>
        <td>${escapeHtml(r.rank_pos ?? "")}</td>
        <td><strong>${escapeHtml(r.defense_team)}</strong></td>
        <td>${escapeHtml(r.value ?? "")}</td>
        <td>${escapeHtml(r.matchup_grade || "")}</td>
      </tr>
    `
    )
    .join("");
}

function escapeHtml(s) {
  return String(s ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

function applyFilters() {
  const q = (searchEl.value || "").toLowerCase().trim();
  const type = typeFilterEl.value;
  const sort = sortByEl.value;

  let filtered = [...rows];

  if (type !== "ALL") {
    filtered = filtered.filter((r) => (r.bet_type || "") === type);
  }

  if (q) {
    filtered = filtered.filter(
      (r) =>
        (r.bet || "").toLowerCase().includes(q) ||
        (r.opponent || "").toLowerCase().includes(q) ||
        (r.bet_type || "").toLowerCase().includes(q) ||
        (r.date || "").toLowerCase().includes(q)
    );
  }

  if (sort === "prob_desc") {
    filtered.sort((a, b) => (b.probability ?? -1) - (a.probability ?? -1));
  } else if (sort === "prob_asc") {
    filtered.sort((a, b) => (a.probability ?? 2) - (b.probability ?? 2));
  } else if (sort === "type") {
    filtered.sort((a, b) => (a.bet_type || "").localeCompare(b.bet_type || ""));
  } else if (sort === "bet") {
    filtered.sort((a, b) => (a.bet || "").localeCompare(b.bet || ""));
  }

  renderBets(filtered);
}

async function loadBetsJson() {
  const res = await fetch(JSON_PATH, { cache: "no-store" });
  if (!res.ok) throw new Error(`HTTP ${res.status} loading ${JSON_PATH}`);
  const data = await res.json();
  return normalizeBets(data);
}

async function loadDvpCsv() {
  const res = await fetch(DVP_CSV_PATH, { cache: "no-store" });
  if (!res.ok) throw new Error(`HTTP ${res.status} loading ${DVP_CSV_PATH}`);
  const text = await res.text();
  const parsed = parseCSV(text);
  return normalizeDvp(parsed);
}

async function loadCsv(path) {
  const res = await fetch(path, { cache: "no-store" });
  if (!res.ok) throw new Error(`HTTP ${res.status} loading ${path}`);
  const text = await res.text();
  return parseCSV(text);
}

/* =========================
   Chart Wheel (3D carousel)
   ========================= */
function initChartWheel() {
  if (!wheelEl || !wheelPrevBtn || !wheelNextBtn || !wheelCounterEl) return;

  const faces = Array.from(wheelEl.querySelectorAll(".wheel-face"));
  if (faces.length < 2) return;

  let index = 0;
  const n = faces.length;

  function layoutFaces() {
    const scene = wheelEl.parentElement; // .wheel-scene
    const w = scene.clientWidth;
    const h = scene.clientHeight;
    const size = Math.max(320, Math.min(w, h));
    const radius = Math.round((size / 2) / Math.tan(Math.PI / n));

    faces.forEach((face, i) => {
      const angle = (360 / n) * i;
      face.style.transform = `rotateY(${angle}deg) translateZ(${radius}px)`;
    });
  }

  function render() {
    const angle = -(360 / n) * index;
    wheelEl.style.transform = `translateZ(0) rotateY(${angle}deg)`;
    wheelCounterEl.textContent = `${index + 1} / ${n}`;
  }

  function prev() {
    index = (index - 1 + n) % n;
    render();
  }
  function next() {
    index = (index + 1) % n;
    render();
  }

  wheelPrevBtn.addEventListener("click", prev);
  wheelNextBtn.addEventListener("click", next);

  // Keyboard nav
  window.addEventListener("keydown", (e) => {
    if (e.key === "ArrowLeft") prev();
    if (e.key === "ArrowRight") next();
  });

  // Swipe support
  let startX = null;
  wheelEl.addEventListener("touchstart", (e) => {
    startX = e.touches[0].clientX;
  }, { passive: true });

  wheelEl.addEventListener("touchend", (e) => {
    if (startX == null) return;
    const endX = e.changedTouches[0].clientX;
    const dx = endX - startX;
    startX = null;
    if (Math.abs(dx) > 40) (dx > 0 ? prev() : next());
  }, { passive: true });

  window.addEventListener("resize", () => {
    layoutFaces();
    render();
  });

  layoutFaces();
  render();
}

/* =========================
   Simple Canvas Charts
   ========================= */
function clearCanvas(cnv) {
  if (!cnv) return;
  const ctx = cnv.getContext("2d");
  ctx.clearRect(0, 0, cnv.width, cnv.height);
}

function drawLineChart(canvas, seriesList, labels) {
  if (!canvas) return;
  const ctx = canvas.getContext("2d");
  const W = canvas.width;
  const H = canvas.height;

  ctx.clearRect(0, 0, W, H);

  // margins
  const mL = 46, mR = 18, mT = 14, mB = 34;
  const x0 = mL, y0 = H - mB;
  const x1 = W - mR, y1 = mT;

  // axes
  ctx.globalAlpha = 0.6;
  ctx.beginPath();
  ctx.moveTo(x0, y1);
  ctx.lineTo(x0, y0);
  ctx.lineTo(x1, y0);
  ctx.strokeStyle = "rgba(255,255,255,0.35)";
  ctx.lineWidth = 1;
  ctx.stroke();
  ctx.globalAlpha = 1;

  // y scale (0..1)
  const yMin = 0;
  const yMax = 1;

  function xAt(i) {
    if (labels.length <= 1) return x0;
    return x0 + (i * (x1 - x0)) / (labels.length - 1);
  }
  function yAt(v) {
    const t = (v - yMin) / (yMax - yMin);
    return y0 - t * (y0 - y1);
  }

  // grid + y ticks
  ctx.font = "12px ui-sans-serif, system-ui";
  ctx.fillStyle = "rgba(255,255,255,0.65)";
  ctx.strokeStyle = "rgba(255,255,255,0.10)";
  ctx.lineWidth = 1;

  for (let p = 0; p <= 1.0001; p += 0.25) {
    const y = yAt(p);
    ctx.beginPath();
    ctx.moveTo(x0, y);
    ctx.lineTo(x1, y);
    ctx.stroke();
    ctx.fillText(`${Math.round(p * 100)}%`, 6, y + 4);
  }

  // x labels (sparse)
  const step = Math.max(1, Math.floor(labels.length / 6));
  ctx.fillStyle = "rgba(255,255,255,0.6)";
  for (let i = 0; i < labels.length; i += step) {
    const x = xAt(i);
    ctx.fillText(labels[i], x - 14, H - 12);
  }

  // series
  seriesList.forEach((s, sIdx) => {
    const vals = s.values;
    ctx.beginPath();
    vals.forEach((v, i) => {
      if (v == null || !Number.isFinite(v)) return;
      const x = xAt(i);
      const y = yAt(v);
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });

    // color separation via alpha (no custom colors requested)
    ctx.strokeStyle = `rgba(122,162,255,${0.85 - sIdx * 0.20})`;
    ctx.lineWidth = 2;
    ctx.stroke();

    // last point marker
    for (let i = vals.length - 1; i >= 0; i--) {
      const v = vals[i];
      if (v == null || !Number.isFinite(v)) continue;
      const x = xAt(i);
      const y = yAt(v);
      ctx.beginPath();
      ctx.arc(x, y, 3.5, 0, Math.PI * 2);
      ctx.fillStyle = `rgba(122,255,214,${0.75 - sIdx * 0.15})`;
      ctx.fill();
      break;
    }
  });

  // legend
  ctx.fillStyle = "rgba(255,255,255,0.75)";
  let lx = x0, ly = 18;
  seriesList.forEach((s, i) => {
    ctx.fillText(s.name, lx, ly);
    lx += ctx.measureText(s.name).width + 18;
    if (lx > W - 140) { lx = x0; ly += 14; }
  });
}

function drawBarChart(canvas, categories, values, counts) {
  if (!canvas) return;
  const ctx = canvas.getContext("2d");
  const W = canvas.width;
  const H = canvas.height;

  ctx.clearRect(0, 0, W, H);

  const mL = 46, mR = 18, mT = 14, mB = 44;
  const x0 = mL, y0 = H - mB;
  const x1 = W - mR, y1 = mT;

  // axes
  ctx.globalAlpha = 0.6;
  ctx.beginPath();
  ctx.moveTo(x0, y1);
  ctx.lineTo(x0, y0);
  ctx.lineTo(x1, y0);
  ctx.strokeStyle = "rgba(255,255,255,0.35)";
  ctx.lineWidth = 1;
  ctx.stroke();
  ctx.globalAlpha = 1;

  // y scale 0..1
  function yAt(v) {
    return y0 - (v * (y0 - y1));
  }

  // grid + y ticks
  ctx.font = "12px ui-sans-serif, system-ui";
  ctx.fillStyle = "rgba(255,255,255,0.65)";
  ctx.strokeStyle = "rgba(255,255,255,0.10)";
  for (let p = 0; p <= 1.0001; p += 0.25) {
    const y = yAt(p);
    ctx.beginPath();
    ctx.moveTo(x0, y);
    ctx.lineTo(x1, y);
    ctx.stroke();
    ctx.fillText(`${Math.round(p * 100)}%`, 6, y + 4);
  }

  if (!categories.length) return;

  const n = categories.length;
  const gap = 10;
  const barW = Math.max(10, Math.floor((x1 - x0 - gap * (n - 1)) / n));

  categories.forEach((cat, i) => {
    const v = values[i] ?? 0;
    const c = counts?.[i] ?? null;

    const x = x0 + i * (barW + gap);
    const y = yAt(v);
    const h = y0 - y;

    ctx.fillStyle = "rgba(122,162,255,0.55)";
    ctx.fillRect(x, y, barW, h);

    ctx.strokeStyle = "rgba(255,255,255,0.18)";
    ctx.strokeRect(x, y, barW, h);

    // value label
    ctx.fillStyle = "rgba(255,255,255,0.75)";
    ctx.fillText(`${Math.round(v * 100)}%`, x + 4, y - 6);

    // x label (bucket)
    ctx.fillStyle = "rgba(255,255,255,0.60)";
    const label = String(cat);
    ctx.fillText(label, x, H - 18);

    // count label
    if (c != null && Number.isFinite(c)) {
      ctx.fillStyle = "rgba(255,255,255,0.45)";
      ctx.fillText(`n=${c}`, x, H - 4);
    }
  });
}

/* =========================
   Charts loader + renderer
   ========================= */
async function loadAndRenderCharts() {
  if (!chartsStatusEl) return;

  try {
    setChartsStatus("Loading charts…");
    const [metricsRaw, bucketsRaw] = await Promise.all([
      loadCsv(METRICS_CSV_PATH),
      loadCsv(BUCKET_CSV_PATH),
    ]);

    // Metrics history: last N points (keep it clean)
    const metrics = metricsRaw
      .map((r) => ({
        eval_date: String(r.eval_date ?? "").trim(),
        overall_accuracy: toNumber(r.overall_accuracy),
        ml_accuracy: toNumber(r.ml_accuracy),
        spread_accuracy: toNumber(r.spread_accuracy),
      }))
      .filter((r) => r.eval_date);

    const N = Math.min(30, metrics.length);
    const tail = metrics.slice(Math.max(0, metrics.length - N));

    const labels = tail.map((r) => {
      // short label: YYYY-MM-DD -> MM-DD
      const s = r.eval_date;
      return s.length >= 10 ? s.slice(5) : s;
    });

    drawLineChart(
      metricsCanvas,
      [
        { name: "Overall", values: tail.map((r) => r.overall_accuracy) },
        { name: "Moneyline", values: tail.map((r) => r.ml_accuracy) },
        { name: "Spread", values: tail.map((r) => r.spread_accuracy) },
      ],
      labels
    );

    if (metricsNoteEl) {
      const last = tail[tail.length - 1];
      const fmt = (x) => (x == null || !Number.isFinite(x) ? "—" : `${Math.round(x * 100)}%`);
      metricsNoteEl.textContent = last
        ? `Latest: Overall ${fmt(last.overall_accuracy)} • ML ${fmt(last.ml_accuracy)} • Spread ${fmt(last.spread_accuracy)}`
        : "No metrics rows yet.";
    }

    // Bucket accuracy
    const buckets = bucketsRaw
      .map((r) => ({
        bucket: String(r.bucket ?? "").trim(),
        mean: toNumber(r.mean),
        count: toNumber(r.count),
      }))
      .filter((r) => r.bucket && r.bucket !== "other");

    // Keep bucket order stable
    buckets.sort((a, b) => a.bucket.localeCompare(b.bucket));

    drawBarChart(
      bucketCanvas,
      buckets.map((r) => r.bucket),
      buckets.map((r) => r.mean ?? 0),
      buckets.map((r) => r.count ?? 0)
    );

    if (bucketNoteEl) {
      bucketNoteEl.textContent = buckets.length
        ? "Tip: buckets with higher count (n) are more trustworthy."
        : "No bucket rows yet.";
    }

    setChartsStatus("Charts Loaded ✅", "ok");
    if (chartsUpdatedEl) chartsUpdatedEl.textContent = `Metrics rows: ${metrics.length} • Buckets: ${buckets.length}`;
  } catch (err) {
    console.warn(err);
    setChartsStatus("Charts missing ⚠️", "bad");
    if (chartsUpdatedEl) chartsUpdatedEl.textContent = "Push metrics_history.csv + bucket_accuracy_latest.csv to /docs";

    // Friendly fallback drawings
    clearCanvas(metricsCanvas);
    clearCanvas(bucketCanvas);
    if (metricsNoteEl) metricsNoteEl.textContent = `Missing ${METRICS_CSV_PATH}`;
    if (bucketNoteEl) bucketNoteEl.textContent = `Missing ${BUCKET_CSV_PATH}`;
  }
}

async function main() {
  initChartWheel();

  // Load Charts (non-fatal)
  await loadAndRenderCharts();

  // Load Bets
  try {
    setStatus("Loading…");
    rows = await loadBetsJson();
    setStatus("Loaded ✅", "ok");
    updatedEl.textContent = `Rows: ${rows.length}`;
    applyFilters();
  } catch (err) {
    console.error(err);
    setStatus("Missing bets_to_place.json ❌", "bad");
    updatedEl.textContent = "Put bets_to_place.json in /docs and push it.";
    bodyEl.innerHTML = `
      <tr>
        <td colspan="6" class="muted">
          Could not load <code>${JSON_PATH}</code>. Make sure it exists in <code>/docs</code>.
        </td>
      </tr>
    `;
  }

  // Load DvP (non-fatal)
  try {
    setDvpStatus("Loading DvP…");
    dvpRows = await loadDvpCsv();
    setDvpStatus("DvP Loaded ✅", "ok");
    if (dvpUpdatedEl) dvpUpdatedEl.textContent = `Rows: ${dvpRows.length}`;

    if (dvpPosEl) {
      const initial = (dvpPosEl.value || "PG").toUpperCase();
      renderDvpTable(initial);
      dvpPosEl.addEventListener("change", (e) =>
        renderDvpTable(String(e.target.value || "PG"))
      );
    } else {
      renderDvpTable("PG");
    }
  } catch (err) {
    console.warn(err);
    setDvpStatus("DvP missing (dvp.csv) ⚠️", "bad");
    if (dvpUpdatedEl) dvpUpdatedEl.textContent = "Put dvp.csv in /docs and push it.";
    if (dvpBodyEl) {
      dvpBodyEl.innerHTML = `
        <tr>
          <td colspan="4" class="muted">
            Could not load <code>${DVP_CSV_PATH}</code>. Make sure it exists in <code>/docs</code>.
          </td>
        </tr>
      `;
    }
  }
}

searchEl.addEventListener("input", applyFilters);
typeFilterEl.addEventListener("change", applyFilters);
sortByEl.addEventListener("change", applyFilters);

main();
